import os, json
from collections import defaultdict, Counter

CREATION = {"create", "build", "generate", "initialize"}

def load_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

def extract_actions(obj):
    # Return a list of action dicts with fields: agent_id, action_type, tick (optional), target (optional)
    out = []
    if isinstance(obj, dict):
        # direct agency schema
        acts = obj.get("actions")
        if isinstance(acts, list):
            for a in acts:
                if isinstance(a, dict):
                    agent = a.get("agent_id") or a.get("agent") or "unknown"
                    atype = a.get("action_type") or a.get("type") or "unknown"
                    rec = {
                        "agent_id": agent,
                        "action_type": atype,
                        "tick": a.get("tick"),
                        "target": a.get("target"),
                    }
                    out.append(rec)
            return out
        # nested common fields
        for k in ["data", "items", "logs"]:
            if isinstance(obj.get(k), list):
                for a in obj[k]:
                    if isinstance(a, dict):
                        agent = a.get("agent_id") or a.get("agent") or "unknown"
                        atype = a.get("action_type") or a.get("type") or "unknown"
                        out.append({
                            "agent_id": agent, "action_type": atype,
                            "tick": a.get("tick"), "target": a.get("target")
                        })
                return out
    elif isinstance(obj, list):
        for a in obj:
            if isinstance(a, dict):
                agent = a.get("agent_id") or a.get("agent") or "unknown"
                atype = a.get("action_type") or a.get("type") or "unknown"
                out.append({
                    "agent_id": agent, "action_type": atype,
                    "tick": a.get("tick"), "target": a.get("target")
                })
        return out
    return out

def ensure_ticks(actions, base_tick=0):
    # Assign sequential ticks if missing; otherwise keep existing
    t = base_tick
    for a in actions:
        if a.get("tick") is None:
            a["tick"] = t
            t += 1
    return actions

def compute_windowed_metrics(actions, window=5):
    # Sort by tick
    actions = [a for a in actions if a.get("tick") is not None]
    actions.sort(key=lambda x: int(x["tick"]))
    # Determine tick range
    ticks = [int(a["tick"]) for a in actions]
    if not ticks:
        return [], []
    tmin, tmax = min(ticks), max(ticks)
    # Novelty tracking
    seen = set()
    novelty_rows = []  # (start, end, new_types, cum_unique_types)
    persistence_rows = []  # (start, end, window_persistence_rate)
    for start in range(tmin, tmax + 1, window):
        end = start + window - 1
        win_acts = [a for a in actions if start <= int(a["tick"]) <= end]
        types_t = {a["action_type"] for a in win_acts}
        new_types = [x for x in types_t if x not in seen]
        seen.update(types_t)
        # window persistence
        cnts = Counter(a["action_type"] for a in win_acts)
        total = sum(cnts.values())
        creation = sum(v for k, v in cnts.items() if k in CREATION)
        pr = (creation / total) if total > 0 else 0.0
        novelty_rows.append((start, end, len(new_types), len(seen)))
        persistence_rows.append((start, end, pr))
    return novelty_rows, persistence_rows

def main():
    base = "storage/shared/agency_lab"
    ax_path = os.path.join(base, "axiom_rng_actions_v1_2b_interactions.json")
    vt_path = os.path.join(base, "data", "veritas_exports", "sample_actions_v1_actions.json")
    prog_paths = [
        os.path.join(base, "data", "progressor_axiom_session_evalunknown.json"),
        os.path.join(base, "data", "progressor_axiom_session_tickunknown.json"),
    ]

    out_dir = os.path.join(base, "analyses")
    os.makedirs(out_dir, exist_ok=True)
    out_json = os.path.join(out_dir, "joint_metrics_v2_2_timesliced.json")
    out_txt = os.path.join(out_dir, "joint_metrics_v2_2_timesliced.txt")

    # Load datasets
    datasets = {}
    if os.path.exists(ax_path):
        datasets["axiom"] = extract_actions(load_json(ax_path))
    if os.path.exists(vt_path):
        vt = load_json(vt_path)
        datasets["veritas"] = extract_actions(vt)
    # Load any progressor files if present
    prog_actions = []
    for p in prog_paths:
        if os.path.exists(p):
            try:
                prog_actions += extract_actions(load_json(p))
            except Exception:
                pass
    if prog_actions:
        datasets["progressor"] = prog_actions

    # Ensure ticks
    base_offset = 0
    combined = []
    per_source = {}
    for name, acts in datasets.items():
        acts = ensure_ticks(acts, base_tick=base_offset)
        # Advance base_offset to maintain global ordering (avoids tick collision if missing)
        if acts:
            base_offset = max(base_offset, int(max(a["tick"] for a in acts)) + 1)
        per_source[name] = acts
        combined += acts

    # Compute sliced metrics
    results = {"window": 5, "sources": {}}
    nov_c, pers_c = compute_windowed_metrics(combined, window=5)
    results["combined"] = {
        "novelty": [{"start": s, "end": e, "new_types": n, "cum_unique_types": c} for s, e, n, c in nov_c],
        "persistence": [{"start": s, "end": e, "persistence_rate": pr} for s, e, pr in pers_c],
    }
    for name, acts in per_source.items():
        nov, per = compute_windowed_metrics(acts, window=5)
        results["sources"][name] = {
            "novelty": [{"start": s, "end": e, "new_types": n, "cum_unique_types": c} for s, e, n, c in nov],
            "persistence": [{"start": s, "end": e, "persistence_rate": pr} for s, e, pr in per],
        }

    # Write JSON
    with open(out_json, "w", encoding="utf-8") as f:
        json.dump(results, f, ensure_ascii=False, indent=2)

    # Write TXT preview
    lines = ["window=5", "section\tstart\tend\tnew_types\tcum_unique_types\tpersistence_rate"]
    # Combined rows, align novelty and persistence by index
    L = max(len(results["combined"]["novelty"]), len(results["combined"]["persistence"]))
    for i in range(L):
        nrow = results["combined"]["novelty"][i] if i < len(results["combined"]["novelty"]) else {}
        prow = results["combined"]["persistence"][i] if i < len(results["combined"]["persistence"]) else {}
        lines.append(f"combined\t{nrow.get('start','')}\t{nrow.get('end','')}\t{nrow.get('new_types','')}\t{nrow.get('cum_unique_types','')}\t{prow.get('persistence_rate','')}")
    lines.append("sources:")
    for name, sec in results["sources"].items():
        Ls = max(len(sec["novelty"]), len(sec["persistence"]))
        for i in range(Ls):
            nrow = sec["novelty"][i] if i < len(sec["novelty"]) else {}
            prow = sec["persistence"][i] if i < len(sec["persistence"]) else {}
            lines.append(f"{name}\t{nrow.get('start','')}\t{nrow.get('end','')}\t{nrow.get('new_types','')}\t{nrow.get('cum_unique_types','')}\t{prow.get('persistence_rate','')}")
    with open(out_txt, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))

    print("WROTE", out_txt)
    print("WROTE", out_json)
    for ln in lines[:12]: print(ln)
    return 0

if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as e:
        print("ERROR", str(e))
        raise SystemExit(1)
